/*
 * A138723  Atomic numbers of the periodic table of the elements, read
 *          downwards along 18 columns, up to the 5th period.
 * https://oeis.org/A138723
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, fini, full, nonn, tabf
 * Formula:   a(n) is the atomic number obtained by reading the periodic table
 *            downwards along its 18 columns (groups) up to the 5th period.
 *            The sequence is generated by determining the column containing
 *            the n‑th element, computing its period and position within that
 *            period, and then adding the corresponding o...
 * Range:     u8 n <= 54, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n < 1) return 0;            /* out of bounds handling */

    /* first atomic number of each period (period index 0‑based) */
    static const seq_t start_atomic[5] = {1, 3, 11, 19, 37};

    /* number of elements present in each of the 18 columns */
    static const idx_t col_counts[18] = {
        5, 4, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2,
        4, 4, 4, 4, 4, 5
    };

    /* starting period index (0‑based) for each column */
    static const idx_t col_start[18] = {
        0, 1, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3,
        1, 1, 1, 1, 1, 0
    };

    idx_t m = n;
    idx_t c;
    for (c = 0; c < 18; ++c) {
        if (m <= col_counts[c]) break;
        m -= col_counts[c];
    }

    /* n is larger than the total length of the sequence */
    if (c >= 18) return 0;

    /* 0‑based offset within the column (row) */
    idx_t r = m - 1;
    /* 0‑based period index */
    idx_t period = col_start[c] + r;

    /* index of the element within its period array */
    idx_t idx_in_period;
    if (period == 0) {                     /* periods 1: only columns 0 and 17 exists */
        idx_in_period = (c == 0) ? 0 : 1;
    } else if (period <= 2) {              /* periods 2–3: columns 0,1 and 12–17 exist */
        idx_in_period = (c <= 1) ? c : (c - 10);
    } else {                               /* periods 4–5: all columns exist */
        idx_in_period = c;
    }

    return start_atomic[period] + (seq_t)idx_in_period;
}
